/**
 * The register grouped by designation, keeping first-appearance order on both
 * axes. Derived rather than stored: the grouping is a reading of the order the
 * register is already in, and storing it would let the two drift apart.
 */
export const rosterByTitle: { title: string; names: string[] }[] = roster.reduce<
  { title: string; names: string[] }[]
>((groups, [name, title]) => {
  const group = groups.find((g) => g.title === title);
  if (group) group.names.push(name);
  else groups.push({ title, names: [name] });
  return groups;
}, []);
